/* ARISE — vanilla JS life RPG. Data stays in this browser's LocalStorage. */
(() => {
'use strict';
const STORE='arise_state_v1';
const DIFFICULTIES={Trivial:5,Easy:10,Normal:20,Hard:35,Elite:50,Legendary:80};
const RANKS=[{name:'E-RANK',min:1},{name:'D-RANK',min:5},{name:'C-RANK',min:10},{name:'B-RANK',min:20},{name:'A-RANK',min:35},{name:'S-RANK',min:50}];
const ATTRS={
 Strength:{icon:'dumbbell',desc:'Physical training, exercise, and resilience.',categories:['Fitness']},
 Intelligence:{icon:'brain',desc:'Learning, reading, and problem-solving.',categories:['Learning','Career']},
 Discipline:{icon:'shield',desc:'Consistency, habits, and follow-through.',categories:['Productivity','Personal Growth']},
 Focus:{icon:'target',desc:'Deep work, concentration, and attention.',categories:['Learning','Productivity']},
 Vitality:{icon:'heart',desc:'Sleep, recovery, and sustainable self-care.',categories:['Fitness','Mental Health']},
 Charisma:{icon:'users',desc:'Communication, confidence, and relationships.',categories:['Social','Personal Growth']}
};
const CATEGORIES=['Fitness','Learning','Career','Productivity','Mental Health','Personal Growth','Social','Custom'];
const ACHIEVEMENTS=[
{id:'first',name:'First Blood',desc:'Complete your first quest.',icon:'swords',test:s=>s.stats.completed>=1},
{id:'awakening',name:'Awakening',desc:'Reach Level 5.',icon:'zap',test:s=>s.profile.level>=5},
{id:'rising',name:'Rising Hunter',desc:'Reach Level 10.',icon:'trending',test:s=>s.profile.level>=10},
{id:'elite',name:'Elite Hunter',desc:'Reach Level 25.',icon:'medal',test:s=>s.profile.level>=25},
{id:'monarch',name:'Shadow Monarch',desc:'Reach Level 50.',icon:'crown',test:s=>s.profile.level>=50},
{id:'streak3',name:'Consistent',desc:'Maintain a 3-day streak.',icon:'flame',test:s=>s.streak.longest>=3},
{id:'streak7',name:'Unbreakable',desc:'Maintain a 7-day streak.',icon:'shield',test:s=>s.streak.longest>=7},
{id:'streak30',name:'Iron Will',desc:'Maintain a 30-day streak.',icon:'fire',test:s=>s.streak.longest>=30},
{id:'quests50',name:'Quest Master',desc:'Complete 50 quests.',icon:'trophy',test:s=>s.stats.completed>=50},
{id:'quests100',name:'Centurion',desc:'Complete 100 quests.',icon:'award',test:s=>s.stats.completed>=100},
{id:'scholar',name:'Scholar',desc:'Complete 10 Learning quests.',icon:'book',test:s=>(s.stats.byCategory.Learning||0)>=10},
{id:'warrior',name:'Warrior',desc:'Complete 10 Fitness quests.',icon:'dumbbell',test:s=>(s.stats.byCategory.Fitness||0)>=10}
];
const ICONS={
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 swords:'<path d="m14 5 5-2 2 2-2 5-7 7-3-3 5-7Z"/><path d="m5 14-2 5 2 2 5-2"/><path d="m8 8 8 8"/><path d="m4 4 4 4"/>',
 user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
 chart:'<path d="M3 3v18h18"/><path d="m7 14 4-4 4 3 5-7"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 trophy:'<path d="M8 21h8M12 17v4M7 4h10v5a5 5 0 0 1-10 0V4Z"/><path d="M7 6H3v2a4 4 0 0 0 4 4M17 6h4v2a4 4 0 0 1-4 4"/>',
 activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
 timer:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M9 2h6M12 2v3"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.6a8 8 0 0 1-1.8 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.8-1l-1.7.6-1.4-2.4L7.1 15a8 8 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.6a8 8 0 0 1 1.8-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.8 1l1.7-.6 1.4 2.4-1.4 1.1a8 8 0 0 1-.1 2Z"/>',
 plus:'<path d="M12 5v14M5 12h14"/>', menu:'<path d="M4 6h16M4 12h16M4 18h16"/>', flame:'<path d="M12 22c4 0 7-3 7-7 0-3-2-5-4-8 0 3-2 4-2 4 0-4-2-7-4-9 0 5-4 8-4 13 0 4 3 7 7 7Z"/><path d="M12 22c-2 0-3-2-3-4s2-3 3-5c1 2 3 3 3 5s-1 4-3 4Z"/>',
 zap:'<path d="m13 2-3 9h7L9 22l2-9H5l8-11Z"/>', trending:'<path d="m3 17 6-6 4 4 8-9"/><path d="M15 6h6v6"/>',
 medal:'<circle cx="12" cy="8" r="5"/><path d="m8 12-2 10 6-3 6 3-2-10"/>', crown:'<path d="m2 8 5 4 5-8 5 8 5-4-2 12H4L2 8Z"/>',
 award:'<circle cx="12" cy="8" r="6"/><path d="m8 13-2 8 6-3 6 3-2-8"/>', book:'<path d="M4 4.5A2.5 2.5 0 0 1 6.5 2H20v17H6.5A2.5 2.5 0 0 0 4 21.5v-17Z"/><path d="M4 17a2 2 0 0 1 2-2h14M8 6h7"/>',
 dumbbell:'<path d="m6.5 6.5 11 11M4 9l5-5M15 20l5-5M3 7l4-4M17 21l4-4"/>', brain:'<path d="M12 5a4 4 0 0 0-7 2 4 4 0 0 0-1 7 4 4 0 0 0 4 6h4V5ZM12 5a4 4 0 0 1 7 2 4 4 0 0 1 1 7 4 4 0 0 1-4 6h-4V5Z"/><path d="M8 8v2M7 15h3M16 8v2M14 15h3"/>',
 shield:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/>', heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.8-7.5 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/>',
 users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8"/>',
 edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/>', trash:'<path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6M10 11v5M14 11v5"/>',
 check:'<path d="m5 12 4 4L19 6"/>', close:'<path d="m18 6-12 12M6 6l12 12"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>', spark:'<path d="m12 3 1.9 5.8L20 11l-6.1 2.2L12 19l-2-5.8L4 11l6-2.2L12 3Z"/><path d="m19 14 1 2 2 1-2 1-1 2-1-2-2-1 2-1 1-2Z"/>',
 download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/>', upload:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 9l5-5 5 5M12 4v12"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.5 9A7 7 0 0 1 17 5l3 2M4 17l3 2a7 7 0 0 0 11.5-4"/>', brain2:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10M7 12h10"/>'
};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.spark}</svg>`}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const uid=()=>`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,9)}`;
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const shiftDate=(key,days)=>{const [y,m,d]=key.split('-').map(Number);const dt=new Date(y,m-1,d);dt.setDate(dt.getDate()+days);return dateKey(dt)};
const niceDate=(key,opts={month:'short',day:'numeric'})=>{if(!key)return 'No date';const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d).toLocaleDateString(undefined,opts)};
const stamp=()=>new Date().toISOString();
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
function defaultState(){return {version:1,setupComplete:false,profile:{name:'Hunter',goal:'Become the strongest version of myself',avatar:'⚔️',level:1,xp:0,lifetimeXP:0,createdAt:stamp(),startingRank:'E-RANK'},settings:{rewards:{...DIFFICULTIES},weekStart:1,morningCutoff:9,focusMinutes:25,shortBreak:5,longBreak:15,reducedMotion:false,sound:false,confirmDelete:true,theme:'blue'},quests:[],completions:[],transactions:[],stats:{completed:0,byCategory:{},byDifficulty:{}},attributes:Object.fromEntries(Object.keys(ATTRS).map(k=>[k,{value:0,lifetime:0}])),goals:[],achievements:{},activityDays:[],focusSessions:[],focus:{duration:25,remaining:1500,running:false,endsAt:null,mode:'focus',associatedQuest:''},createdAt:stamp()}}
function safeParse(raw){try{return JSON.parse(raw)}catch{return null}}
function validateState(s){return !!s&&typeof s==='object'&&s.version===1&&s.profile&&Array.isArray(s.quests)&&Array.isArray(s.completions)&&Array.isArray(s.transactions)&&s.settings&&s.attributes}
let state=loadState();
function loadState(){try{const raw=localStorage.getItem(STORE);if(!raw)return defaultState();const parsed=safeParse(raw);if(validateState(parsed))return parsed;console.warn('ARISE saved state failed validation; keeping a recoverable backup.');if(raw)localStorage.setItem(STORE+'_recovery_'+Date.now(),raw);return defaultState()}catch(e){console.warn('Storage unavailable',e);return defaultState()}}
function saveState(){try{localStorage.setItem(STORE,JSON.stringify(state));return true}catch(e){toast('STORAGE WARNING','Could not save data. Export your progress and free browser storage.','warning');return false}}
function rankFor(level){return [...RANKS].reverse().find(r=>level>=r.min)?.name||'E-RANK'}
function xpNeed(level){return 100+(level-1)*25}
function xpTotalAtLevel(level){let total=0;for(let l=1;l<level;l++)total+=xpNeed(l);return total}
function currentLevelFromLifetime(total){let level=1,left=Math.max(0,total);while(left>=xpNeed(level)&&level<10000){left-=xpNeed(level);level++}return {level,xp:left,need:xpNeed(level)}}
function syncLevel(){const x=currentLevelFromLifetime(state.profile.lifetimeXP);state.profile.level=x.level;state.profile.xp=x.xp;return x}
function todayCompletions(){const t=dateKey();return state.completions.filter(c=>c.date===t)}
function activeDates(){return [...new Set(state.completions.filter(c=>c.eligible!==false).map(c=>c.date))].sort()}
function computeStreak(){const dates=activeDates();if(!dates.length)return {current:0,longest:0,activeDays:0,last:null};let current=0, longest=0,run=0,prev=null;for(const d of dates){if(prev&&shiftDate(prev,1)===d)run++;else run=1;longest=Math.max(longest,run);prev=d}const today=dateKey(),last=dates[dates.length-1];if(last===today||last===shiftDate(today,-1)){let d=last;current=1;while(dates.includes(shiftDate(d,-1))){d=shiftDate(d,-1);current++}}return {current,longest:Math.max(longest,state.streak?.longest||0),activeDays:dates.length,last}}
function refreshDerived(){state.stats.completed=state.completions.length;state.stats.byCategory={};state.stats.byDifficulty={};state.completions.forEach(c=>{state.stats.byCategory[c.category]=(state.stats.byCategory[c.category]||0)+1;state.stats.byDifficulty[c.difficulty]=(state.stats.byDifficulty[c.difficulty]||0)+1});state.streak=computeStreak();syncLevel()}
function toast(title,message,type='info'){const region=$('#toast-region');if(!region)return;const el=document.createElement('div');el.className='toast';const sym=type==='success'?'check':type==='warning'?'activity':'spark';el.innerHTML=`<div class="toast-symbol">${icon(sym)}</div><div class="toast-copy"><strong>${escapeHTML(title)}</strong><p>${escapeHTML(message)}</p></div><button class="toast-close" aria-label="Dismiss notification">${icon('close')}</button>`;region.append(el);const remove=()=>el.remove();el.querySelector('.toast-close').addEventListener('click',remove);setTimeout(remove,5500)}
function maybeAchievements(){const unlocked=[];ACHIEVEMENTS.forEach(a=>{if(!state.achievements[a.id]&&a.test(state)){state.achievements[a.id]={unlockedAt:stamp()};unlocked.push(a)}});unlocked.forEach(a=>toast('ACHIEVEMENT UNLOCKED',`${a.name} — ${a.desc}`,'success'));return unlocked}
function awardXP(amount,reason,questId=null){const before=state.profile.level;state.profile.lifetimeXP=Math.max(0,state.profile.lifetimeXP+amount);const after=syncLevel();state.transactions.push({id:uid(),amount,reason,questId,at:stamp(),date:dateKey()});if(after.level>before){toast('LEVEL UP',`Level ${before} → ${after.level}. Your effort is becoming your power.`,'success');if(rankFor(before)!==rankFor(after.level))toast('NEW RANK ACHIEVED',`You have ascended to ${rankFor(after.level)}.`,'success')}return {before,after}}
function getStatGain(difficulty){return ['Trivial','Easy'].includes(difficulty)?1:['Normal','Hard'].includes(difficulty)?2:3}
function statTargets(q){if(Array.isArray(q.attributes)&&q.attributes.length)return q.attributes.filter(k=>ATTRS[k]);const cat=q.category;const matched=Object.keys(ATTRS).filter(k=>ATTRS[k].categories.includes(cat));return matched.length?matched:['Discipline']}
function completeQuest(id,occurrence=dateKey()){const q=state.quests.find(q=>q.id===id);if(!q||q.archived)return;if(state.completions.some(c=>c.questId===id&&c.occurrence===occurrence)){toast('ALREADY COMPLETED','This quest occurrence has already been rewarded.');return}const now=stamp(),xp=clamp(Number(q.xp)||state.settings.rewards[q.difficulty]||20,1,500);const completion={id:uid(),questId:id,title:q.title,category:q.category,difficulty:q.difficulty,xp,date:dateKey(),occurrence,at:now,eligible:true,attributes:statTargets(q),statGain:getStatGain(q.difficulty)};state.completions.push(completion);q.lastCompleted=now;if(!q.repeat||q.repeat==='Never')q.completed=true;completion.attributes.forEach(k=>{state.attributes[k].value+=completion.statGain;state.attributes[k].lifetime+=completion.statGain});awardXP(xp,`Quest: ${q.title}`,id);if(q.goalId){const g=state.goals.find(g=>g.id===q.goalId);if(g&&q.goalContribution){g.progress=clamp((g.progress||0)+Number(q.goalContribution),0,100);if(g.progress===100)g.status='Completed'}}refreshDerived();maybeAchievements();saveState();render();toast('QUEST COMPLETED',`+${xp} XP acquired from “${q.title}”.`,'success')}
function undoCompletion(completionId){const c=state.completions.find(x=>x.id===completionId);if(!c)return;if(!confirm(`Undo "${c.title}"? This reverses its XP and attribute gains.`))return;state.completions=state.completions.filter(x=>x.id!==completionId);const tx=state.transactions.find(t=>t.questId===c.questId&&t.reason===`Quest: ${c.title}`&&t.date===c.date&&t.amount===c.xp);if(tx){state.profile.lifetimeXP=Math.max(0,state.profile.lifetimeXP-tx.amount);state.transactions.push({id:uid(),amount:-tx.amount,reason:`Undo: ${c.title}`,questId:c.questId,at:stamp(),date:dateKey(),reversalOf:tx.id})}c.attributes?.forEach(k=>{if(state.attributes[k])state.attributes[k].value=Math.max(0,state.attributes[k].value-(c.statGain||0))});const q=state.quests.find(q=>q.id===c.questId);if(q&&!q.repeat)q.completed=false;refreshDerived();saveState();render();toast('COMPLETION REVERSED','XP and stat changes were adjusted.','warning')}
function createQuest(data){const q={id:uid(),title:data.title.trim(),description:data.description.trim(),category:data.category,difficulty:data.difficulty,xp:clamp(Number(data.xp)||state.settings.rewards[data.difficulty]||20,1,500),duration:clamp(Number(data.duration)||25,1,1440),dueDate:data.dueDate||'',repeat:data.repeat||'Never',weekdays:data.weekdays||[],tags:data.tags.split(',').map(x=>x.trim()).filter(Boolean),createdAt:stamp(),completed:false,archived:false,goalId:data.goalId||'',goalContribution:Number(data.goalContribution)||0,attributes:data.attributes||[]};state.quests.unshift(q);saveState();render();toast('QUEST REGISTERED',`“${q.title}” added to your quest log.`,'success')}
function updateQuest(id,data){const q=state.quests.find(x=>x.id===id);if(!q)return;Object.assign(q,{title:data.title.trim(),description:data.description.trim(),category:data.category,difficulty:data.difficulty,xp:clamp(Number(data.xp)||state.settings.rewards[data.difficulty]||20,1,500),duration:clamp(Number(data.duration)||25,1,1440),dueDate:data.dueDate||'',repeat:data.repeat||'Never',weekdays:data.weekdays||[],tags:data.tags.split(',').map(x=>x.trim()).filter(Boolean),goalId:data.goalId||'',goalContribution:Number(data.goalContribution)||0,attributes:data.attributes||[]});saveState();render();toast('QUEST UPDATED','Quest details saved.')}
function deleteQuest(id){const q=state.quests.find(q=>q.id===id);if(!q)return;if(state.settings.confirmDelete&&!confirm(`Delete "${q.title}"? Existing completion history will be preserved.`))return;state.quests=state.quests.filter(x=>x.id!==id);saveState();render();toast('QUEST REMOVED','The quest was removed. Past history remains.')}
function questForm(id=null){const old=state.quests.find(q=>q.id===id);const categories=[...new Set([...CATEGORIES,...state.quests.map(q=>q.category)])];const goals=state.goals.filter(g=>g.status!=='Archived');const modal=$('#modal-root');modal.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="quest-modal-title"><div class="modal-head"><h2 id="quest-modal-title">${old?'EDIT QUEST':'REGISTER NEW QUEST'}</h2><button class="icon-button" data-close aria-label="Close">${icon('close')}</button></div><form id="quest-form"><div class="modal-body"><div class="form-grid"><div class="form-group full"><label for="q-title">Quest title *</label><input class="field" id="q-title" name="title" required maxlength="100" placeholder="e.g. Complete a focused study session" value="${escapeHTML(old?.title||'')}"></div><div class="form-group full"><label for="q-description">Description</label><textarea class="textarea" id="q-description" name="description" maxlength="500" placeholder="What does success look like?">${escapeHTML(old?.description||'')}</textarea></div><div class="form-group"><label for="q-category">Category</label><select class="select" id="q-category" name="category">${categories.map(c=>`<option ${old?.category===c?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select></div><div class="form-group"><label for="q-difficulty">Difficulty</label><select class="select" id="q-difficulty" name="difficulty">${Object.keys(state.settings.rewards).map(d=>`<option ${old?.difficulty===d?'selected':''}>${d}</option>`).join('')}</select></div><div class="form-group"><label for="q-xp">XP reward (custom optional)</label><input class="field" id="q-xp" name="xp" type="number" min="1" max="500" placeholder="Use difficulty default" value="${old?.xp??''}"><div class="xp-preview" id="xp-preview">✦ ${old?.xp??state.settings.rewards[old?.difficulty||'Normal']} XP reward</div></div><div class="form-group"><label for="q-duration">Duration (minutes)</label><input class="field" id="q-duration" name="duration" type="number" min="1" max="1440" value="${old?.duration||25}"></div><div class="form-group"><label for="q-due">Due date</label><input class="field" id="q-due" name="dueDate" type="date" value="${old?.dueDate||''}"></div><div class="form-group"><label for="q-repeat">Repeat schedule</label><select class="select" id="q-repeat" name="repeat">${['Never','Daily','Weekdays','Weekly'].map(x=>`<option ${old?.repeat===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-group full"><label for="q-tags">Tags (comma-separated)</label><input class="field" id="q-tags" name="tags" placeholder="exam, priority, morning" value="${escapeHTML((old?.tags||[]).join(', '))}"></div><div class="form-group"><label for="q-goal">Linked main quest</label><select class="select" id="q-goal" name="goalId"><option value="">None</option>${goals.map(g=>`<option value="${g.id}" ${old?.goalId===g.id?'selected':''}>${escapeHTML(g.title)}</option>`).join('')}</select></div><div class="form-group"><label for="q-contribution">Goal progress per completion (%)</label><input class="field" id="q-contribution" name="goalContribution" type="number" min="0" max="100" value="${old?.goalContribution||0}"></div><div class="form-group full"><label>Attributes improved</label><div class="pill-row">${Object.keys(ATTRS).map(a=>`<label class="tag"><input type="checkbox" name="attributes" value="${a}" ${(old?.attributes?.length?old.attributes:[]).includes(a)?'checked':''}> ${a}</label>`).join('')}</div><span class="help-text">If none are selected, attributes are mapped automatically from the quest category.</span></div></div></div><div class="modal-foot"><button type="button" class="btn ghost" data-close>Cancel</button><button class="btn primary" type="submit">${icon('check')} ${old?'Save changes':'Create quest'}</button></div></form></section></div>`;
modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.innerHTML='');modal.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))modal.innerHTML=''});const diff=modal.querySelector('#q-difficulty'),xp=modal.querySelector('#q-xp'),prev=modal.querySelector('#xp-preview');diff.addEventListener('change',()=>{if(!xp.value)prev.textContent=`✦ ${state.settings.rewards[diff.value]} XP reward`;});xp.addEventListener('input',()=>{prev.textContent=`✦ ${clamp(Number(xp.value)||state.settings.rewards[diff.value],1,500)} XP reward`});modal.querySelector('#quest-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const data=Object.fromEntries(fd.entries());data.attributes=fd.getAll('attributes');data.weekdays=[];if(!data.xp)data.xp=state.settings.rewards[data.difficulty];if(old)updateQuest(id,data);else createQuest(data);modal.innerHTML=''});modal.querySelector('#q-title').focus()}
function goalForm(id=null){const old=state.goals.find(g=>g.id===id);const modal=$('#modal-root');modal.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${old?'EDIT MAIN QUEST':'CREATE MAIN QUEST'}</h2><button class="icon-button" data-close>${icon('close')}</button></div><form id="goal-form"><div class="modal-body"><div class="form-grid"><div class="form-group full"><label>Goal title *</label><input class="field" name="title" required maxlength="100" value="${escapeHTML(old?.title||'')}" placeholder="e.g. Build a full-stack portfolio"></div><div class="form-group full"><label>Description</label><textarea class="textarea" name="description">${escapeHTML(old?.description||'')}</textarea></div><div class="form-group"><label>Category</label><select class="select" name="category">${CATEGORIES.map(c=>`<option ${old?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-group"><label>Target date</label><input class="field" type="date" name="targetDate" value="${old?.targetDate||''}"></div><div class="form-group"><label>Progress (%)</label><input class="field" type="number" min="0" max="100" name="progress" value="${old?.progress||0}"></div><div class="form-group"><label>Status</label><select class="select" name="status">${['Active','Completed','Archived'].map(x=>`<option ${old?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-group full"><label>Milestones (one per line)</label><textarea class="textarea" name="milestones" placeholder="Plan the project&#10;Build the MVP&#10;Deploy">${escapeHTML((old?.milestones||[]).map(m=>m.title).join('\n'))}</textarea></div></div></div><div class="modal-foot"><button type="button" class="btn ghost" data-close>Cancel</button><button class="btn primary">Save main quest</button></div></form></section></div>`;modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.innerHTML='');modal.querySelector('#goal-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget),d=Object.fromEntries(fd.entries());const milestones=d.milestones.split('\n').map(x=>x.trim()).filter(Boolean).map((title,i)=>({id:old?.milestones?.[i]?.id||uid(),title,done:old?.milestones?.[i]?.title===title?old.milestones[i].done:false}));const obj={...(old||{}),id:old?.id||uid(),title:d.title.trim(),description:d.description.trim(),category:d.category,targetDate:d.targetDate,progress:clamp(Number(d.progress)||0,0,100),status:d.status,milestones,createdAt:old?.createdAt||stamp()};if(!old)state.goals.unshift(obj);else state.goals=state.goals.map(g=>g.id===id?obj:g);saveState();modal.innerHTML='';render();toast('MAIN QUEST UPDATED',obj.title,'success')}}
function onboarding(){const root=document.createElement('div');root.className='onboarding';root.innerHTML=`<section class="onboarding-card"><div class="onboard-logo"><svg viewBox="0 0 40 40" fill="none"><path d="M20 3 36 32H4L20 3Z" stroke="currentColor" stroke-width="2"/><path d="M20 13 27 28H13L20 13Z" fill="currentColor"/></svg> ARISE / SYSTEM BOOT</div><div class="eyebrow" style="margin-top:32px">INITIALIZATION REQUIRED</div><h1>THE SYSTEM<br>HAS <span>AWAKENED.</span></h1><p class="subhead">Your old limits are not your final form. Turn your real-life effort into measurable progression—one quest at a time.</p><form class="onboarding-form" id="onboard-form"><div><label for="player-name">PLAYER NAME / ALIAS</label><input class="field" id="player-name" name="name" required maxlength="32" placeholder="What should the System call you?"></div><div><label for="player-goal">PRIMARY LIFE GOAL</label><input class="field" id="player-goal" name="goal" required maxlength="140" placeholder="e.g. Become a skilled full-stack developer"></div><div><label for="player-avatar">CHOOSE YOUR EMBLEM</label><select class="select" id="player-avatar" name="avatar"><option>⚔️</option><option>🛡️</option><option>🦅</option><option>🐺</option><option>🔥</option><option>🌌</option><option>🧠</option><option>⚡</option></select></div><button class="btn primary" type="submit" style="padding:14px">INITIALIZE SYSTEM ${icon('zap')}</button></form><div class="onboard-foot"><i></i> LOCAL PROFILE · OFFLINE READY · PROGRESS IS YOURS</div></section>`;document.body.append(root);$('#onboard-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.profile.name=fd.get('name').trim();state.profile.goal=fd.get('goal').trim();state.profile.avatar=fd.get('avatar');state.setupComplete=true;saveState();root.remove();toast('SYSTEM INITIALIZED',`Welcome, ${state.profile.name}. Your journey begins now.`,'success');render()}}
function render(){refreshDerived();document.body.classList.toggle('reduce-motion',!!state.settings.reducedMotion);$('#side-player').innerHTML=`<div class="sp-top"><div class="player-orb">${escapeHTML(state.profile.avatar)}</div><div><div class="sp-name">${escapeHTML(state.profile.name)}</div><div class="sp-level">${rankFor(state.profile.level)} · LEVEL ${state.profile.level}</div></div></div><div class="mini-track"><div class="track-fill" style="width:${state.profile.xp/xpNeed(state.profile.level)*100}%"></div></div><div class="sp-xp"><span>${state.profile.xp} / ${xpNeed(state.profile.level)} XP</span><span>${Math.floor(state.profile.xp/xpNeed(state.profile.level)*100)}%</span></div>`;$('#avatar-mini').textContent=state.profile.avatar;$('#footer-date').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'}).toUpperCase();$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));if(!state.setupComplete){if(!$('.onboarding'))onboarding();return}const page=window.currentPage||'dashboard';const titles={dashboard:'DASHBOARD',quests:'QUEST LOG',character:'CHARACTER STATUS',stats:'SKILLS & STATS',goals:'MAIN QUESTS',achievements:'ACHIEVEMENTS',analytics:'HISTORY & ANALYTICS',focus:'FOCUS MODE',settings:'SYSTEM SETTINGS'};$('#page-title').textContent=titles[page]||'DASHBOARD';$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));const renderers={dashboard:renderDashboard,quests:renderQuests,character:renderCharacter,stats:renderStats,goals:renderGoals,achievements:renderAchievements,analytics:renderAnalytics,focus:renderFocus,settings:renderSettings};$('#view').innerHTML=(renderers[page]||renderDashboard)();wireCommon();wirePage(page)}
function heading(eyebrow,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subhead">${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function btn(text,action,kind='primary',ic='plus'){return `<button class="btn ${kind}" data-action="${action}">${icon(ic)} ${text}</button>`}
function metric(label,value,note,ic,positive=''){return `<article class="panel metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(ic)}</span></div><div class="metric-value">${value}</div><div class="metric-note ${positive}">${note}</div></article>`}
function empty(title,desc,action,label,ic='spark'){return `<div class="empty-state"><div class="empty-icon">${icon(ic)}</div><h3>${title}</h3><p>${desc}</p>${action?btn(label,action,'primary','plus'):''}</div>`}
function questRow(q,done=false){return `<div class="quest-row"><button class="quest-check ${done?'done':''}" data-complete="${q.id}" aria-label="${done?'Already completed':'Complete '+escapeHTML(q.title)}" ${done?'disabled':''}>${icon('check')}</button><div class="quest-row-main"><div class="quest-row-title">${escapeHTML(q.title)}</div><div class="quest-row-meta"><span>${escapeHTML(q.category)}</span><span>·</span><span>${q.duration} MIN</span>${q.dueDate?`<span>· ${niceDate(q.dueDate)}</span>`:''}</div></div><span class="xp-chip">+${q.xp} XP</span></div>`}
function getTodayQuests(){return state.quests.filter(q=>!q.archived&&(!q.completed||q.repeat&&q.repeat!=='Never')&&(!q.dueDate||q.dueDate<=dateKey()||q.repeat==='Daily'||q.repeat==='Weekdays'))}
function renderDashboard(){const active=getTodayQuests(),done=state.completions.filter(c=>c.date===dateKey()),doneIds=new Set(done.map(c=>c.questId));const planned=active.length+done.filter(c=>!active.some(q=>q.id===c.questId)).length;const percent=planned?Math.round(done.length/planned*100):0;const streak=state.streak||computeStreak();const goal=state.goals.find(g=>g.status==='Active');const attrs=Object.keys(ATTRS).map(k=>`<div class="attr-mini-row"><label>${k}</label><div class="track"><div class="track-fill" style="width:${Math.min(100,state.attributes[k].value)}%"></div></div><b>${state.attributes[k].value}</b></div>`).join('');const recent=[...state.completions].sort((a,b)=>b.at.localeCompare(a.at)).slice(0,4);return `${heading('YOUR JOURNEY, IN REAL TIME',`Welcome back, ${escapeHTML(state.profile.name)}.`,`The System is online. Small actions compound into extraordinary progress.`,btn('New Quest','new-quest','primary','plus'))}<div class="grid dashboard-grid"><div><section class="panel hero-panel"><div class="hero-content"><div><div class="eyebrow">CURRENT HUNTER STATUS</div><div class="hero-name">${escapeHTML(state.profile.name)}</div><p class="hero-goal">${escapeHTML(state.profile.goal||'Define your primary life goal in settings.')}</p><div class="rank-pill">${icon('shield')} ${rankFor(state.profile.level)} HUNTER</div></div><div class="level-emblem"><div class="emblem-inner"><small>LEVEL</small><strong>${state.profile.level}</strong><small>HUNTER</small></div></div></div><div class="xp-block"><div class="xp-meta"><span>EXPERIENCE PROGRESSION</span><strong>${state.profile.xp} / ${xpNeed(state.profile.level)} XP</strong></div><div class="track"><div class="track-fill" style="width:${state.profile.xp/xpNeed(state.profile.level)*100}%"></div></div><div class="hero-bottom"><span>LIFETIME XP <b>${state.profile.lifetimeXP.toLocaleString()}</b></span><span>NEXT LEVEL <b>${xpNeed(state.profile.level)-state.profile.xp} XP TO GO</b></span></div></div></section><div class="grid stat-cards">${metric('QUESTS COMPLETED',state.stats.completed,'Lifetime completions','check','positive')}${metric('XP EARNED TODAY',done.reduce((n,c)=>n+c.xp,0),'From completed quests','zap','positive')}${metric('CURRENT STREAK',streak.current,`Longest: ${streak.longest} days`,'flame')}${metric('ACTIVE DAYS',streak.activeDays,'Days with qualifying activity','calendar')}</div><section class="panel today-panel"><div class="panel-head"><div><h2>⚔️ Today's Quests</h2><p class="subhead" style="margin-top:5px">Every completed quest moves you forward.</p></div><button class="section-link" data-nav="quests">VIEW QUEST LOG ↗</button></div>${active.length?`<div class="quest-list">${active.slice(0,5).map(q=>questRow(q,doneIds.has(q.id))).join('')}</div>${active.length>5?`<p class="subhead mt-15">${active.length-5} more quests in your quest log.</p>`:''}`:empty('No active quests','Your next level begins with one action. Register a quest to get started.','new-quest','Create your first quest','swords')}<div class="separator"></div><div class="goal-line"><strong>DAILY COMPLETION</strong><span>${percent}%</span></div><div class="track"><div class="track-fill" style="width:${percent}%"></div></div></section><section class="panel panel-pad mt-15"><div class="panel-head"><div><h2>◈ Recent Activity</h2><p class="subhead">Your latest progression events.</p></div><button class="section-link" data-nav="analytics">VIEW HISTORY ↗</button></div>${recent.length?`<div class="activity-list">${recent.map(c=>`<div class="activity-item"><div class="activity-icon">${icon('check')}</div><div class="activity-copy"><strong>${escapeHTML(c.title)}</strong><p>Quest completed · ${escapeHTML(c.category)}</p></div><span class="xp-chip">+${c.xp} XP</span></div>`).join('')}</div>`:empty('No activity recorded','Complete your first quest to create a history of progress.')}</section></div><div class="side-stack"><section class="panel streak-panel"><div class="panel-head"><div><div class="eyebrow">CONSISTENCY PROTOCOL</div><h2 style="margin-top:8px">Daily Streak</h2></div>${icon('flame')}</div><div class="streak-number"><div class="streak-flame">🔥</div><div><strong>${streak.current}</strong><span>DAY CURRENT STREAK</span></div></div><div class="week-strip">${Array.from({length:7},(_,i)=>{const d=shiftDate(dateKey(),i-6),activeDate=activeDates().includes(d),day=new Date(d+'T12:00:00').toLocaleDateString(undefined,{weekday:'narrow'});return `<div class="week-day">${day}<div class="week-dot ${activeDate?'active':''} ${d===dateKey()?'today':''}">${activeDate?icon('check'):(new Date(d+'T12:00:00').getDate())}</div></div>`}).join('')}</div><div class="goal-meta"><span>LONGEST STREAK</span><span>${streak.longest} DAYS</span></div></section><section class="panel goal-mini"><div class="panel-head"><h2>🎯 Main Quest</h2><button class="section-link" data-nav="goals">ALL GOALS ↗</button></div>${goal?`<span class="tag violet">${escapeHTML(goal.category)}</span><div class="goal-line"><strong>${escapeHTML(goal.title)}</strong><span>${goal.progress}%</span></div><div class="track"><div class="track-fill" style="width:${goal.progress}%"></div></div><div class="goal-meta"><span>${goal.targetDate?'TARGET '+niceDate(goal.targetDate):'NO DEADLINE SET'}</span><span>${goal.milestones.filter(m=>m.done).length}/${goal.milestones.length} MILESTONES</span></div>`:empty('No main quest selected','Set a long-term target to keep your daily effort connected.','new-goal','Create main quest','target')}</section><section class="panel attributes-mini"><div class="panel-head"><h2>✧ Attributes</h2><button class="section-link" data-nav="stats">STATUS ↗</button></div>${attrs}</section><section class="panel panel-pad"><div class="panel-head"><h2>⚡ Quick Actions</h2></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:8px"><button class="btn ghost" data-nav="focus">${icon('timer')} Focus session</button><button class="btn ghost" data-nav="character">${icon('user')} Character</button><button class="btn ghost" data-nav="analytics">${icon('chart')} Analytics</button><button class="btn ghost" data-nav="settings">${icon('settings')} Settings</button></div></section></div></div>`}
function renderQuests(){const qs=state.quests.filter(q=>!q.archived);const active=qs.filter(q=>!q.completed||q.repeat!=='Never');const completed=state.completions.slice().sort((a,b)=>b.at.localeCompare(a.at));return `${heading('MISSION CONTROL','Quest Log','Register, complete, and review the real work behind your progression.',btn('Create Quest','new-quest','primary','plus'))}<div class="filter-bar"><input class="field" id="quest-search" placeholder="⌕  Search quests by title..." aria-label="Search quests"><select class="select" id="filter-category"><option value="">All categories</option>${[...new Set([...CATEGORIES,...qs.map(q=>q.category)])].map(c=>`<option>${escapeHTML(c)}</option>`).join('')}</select><select class="select" id="filter-difficulty"><option value="">All difficulties</option>${Object.keys(DIFFICULTIES).map(d=>`<option>${d}</option>`).join('')}</select><select class="select" id="filter-status"><option value="active">Active quests</option><option value="all">All quests</option><option value="completed">Completed only</option></select><select class="select" id="sort-quests"><option value="created">Newest first</option><option value="xp">Highest XP</option><option value="difficulty">Difficulty</option><option value="due">Due date</option></select></div><div class="panel panel-pad"><div class="panel-head"><div><h2>⚔️ Active &amp; Daily Quests</h2><p class="subhead" style="margin-top:5px"><span id="quest-count">${active.length}</span> available quests · rewards only on completion</p></div><span class="tag blue">XP SYSTEM ONLINE</span></div><div class="quest-cards" id="quest-card-list">${active.length?active.map(questCard).join(''):empty('Your quest log is quiet','Create a meaningful task and begin earning experience.','new-quest','Register a quest','swords')}</div></div><div class="panel panel-pad mt-15"><div class="panel-head"><div><h2>◷ Completion History</h2><p class="subhead" style="margin-top:5px">Past completions remain recorded, even when a quest is removed.</p></div><span class="tag green">${completed.length} RECORDED</span></div>${completed.length?`<div class="history-list">${completed.slice(0,12).map(c=>`<div class="history-row"><div class="history-date">${niceDate(c.date,{month:'short',day:'numeric',year:'numeric'})}</div><div><div class="history-title">${escapeHTML(c.title)}</div><div class="history-sub">${escapeHTML(c.category)} · ${escapeHTML(c.difficulty)}</div></div><div class="history-xp">+${c.xp} XP<br><button class="section-link" data-undo="${c.id}">UNDO</button></div></div>`).join('')}</div>`:empty('No completions yet','Complete a quest to start building your activity record.')}</div>`}
function questCard(q){const past=state.completions.some(c=>c.questId===q.id);return `<article class="quest-card ${q.completed?'completed':''}" data-quest-card="${q.id}"><div class="quest-card-top"><div class="tag-row"><span class="tag blue">${escapeHTML(q.category)}</span><span class="tag ${q.difficulty==='Legendary'||q.difficulty==='Elite'?'amber':q.difficulty==='Hard'?'violet':''}">${escapeHTML(q.difficulty)}</span></div><span class="xp-chip">✦ ${q.xp} XP</span></div><h3>${escapeHTML(q.title)}</h3><p>${escapeHTML(q.description||'No description provided.')}</p><div class="tag-row"><span class="tag">${icon('clock')} ${q.duration} min</span><span class="tag">${icon('refresh')} ${escapeHTML(q.repeat||'Never')}</span>${q.dueDate?`<span class="tag">${icon('calendar')} ${niceDate(q.dueDate)}</span>`:''}${q.tags.map(t=>`<span class="tag">#${escapeHTML(t)}</span>`).join('')}</div><div class="quest-card-foot"><span class="muted mono" style="font-size:9px">${q.completed?'✓ COMPLETED':past?'REPEATABLE QUEST':'READY FOR ACTION'}</span><div class="quest-actions">${!q.completed||q.repeat!=='Never'?`<button class="btn small primary" data-complete="${q.id}">${icon('check')} Complete</button>`:''}<button class="icon-action" data-edit="${q.id}" aria-label="Edit quest">${icon('edit')}</button><button class="icon-action" data-delete="${q.id}" aria-label="Delete quest">${icon('trash')}</button></div></div></article>`}
function renderCharacter(){const s=state.streak||computeStreak();return `${heading('IDENTITY & PROGRESSION','Character Status','Your real-world effort, represented as a growing hunter profile.',btn('Edit Profile','edit-profile','ghost','edit'))}<section class="panel character-hero"><div class="avatar-large">${escapeHTML(state.profile.avatar)}</div><div class="character-info"><div class="eyebrow">HUNTER PROFILE / ${rankFor(state.profile.level)}</div><h2>${escapeHTML(state.profile.name)}</h2><p class="subhead">${escapeHTML(state.profile.goal)}</p><div class="character-details"><span class="rank-pill">${icon('shield')} ${rankFor(state.profile.level)}</span><span class="detail-pill">LEVEL <strong>${state.profile.level}</strong></span><span class="detail-pill">CREATED <strong>${niceDate(dateKey(new Date(state.profile.createdAt)))}</strong></span></div><div class="xp-meta"><span>LEVEL PROGRESSION</span><strong>${state.profile.xp} / ${xpNeed(state.profile.level)} XP</strong></div><div class="track"><div class="track-fill" style="width:${state.profile.xp/xpNeed(state.profile.level)*100}%"></div></div><div class="profile-stats"><div class="profile-stat"><span>LIFETIME XP</span><strong>${state.profile.lifetimeXP.toLocaleString()}</strong></div><div class="profile-stat"><span>QUESTS DONE</span><strong>${state.stats.completed}</strong></div><div class="profile-stat"><span>CURRENT STREAK</span><strong>${s.current} 🔥</strong></div></div></div></section><div class="grid stat-cards">${metric('NEXT LEVEL REQUIREMENT',xpNeed(state.profile.level),'Current level threshold','zap')}${metric('XP TO NEXT LEVEL',xpNeed(state.profile.level)-state.profile.xp,'Keep moving forward','trending')}${metric('LONGEST STREAK',s.longest,'Personal best','flame')}${metric('ACTIVE DAYS',s.activeDays,'Days with quest activity','calendar')}</div><div class="panel panel-pad"><div class="panel-head"><div><h2>◈ Rank progression</h2><p class="subhead" style="margin-top:5px">Rank is automatically determined by level.</p></div></div><div class="grid" style="grid-template-columns:repeat(3,1fr);gap:10px">${RANKS.map(r=>`<div class="profile-stat" style="border-color:${rankFor(state.profile.level)===r.name?'#4ca7ff77':'var(--line)'}"><span>${rankFor(state.profile.level)===r.name?'CURRENT RANK':'RANK TIER'}</span><strong style="font-size:14px;color:${rankFor(state.profile.level)===r.name?'var(--cyan)':'var(--text)'}">${r.name}</strong><div class="help-text" style="margin-top:7px">Level ${r.min}${RANKS[RANKS.indexOf(r)+1]?`–${RANKS[RANKS.indexOf(r)+1].min-1}`:'+'}</div></div>`).join('')}</div></div>`}
function renderStats(){return `${heading('ATTRIBUTE ALLOCATION','Skills & Stats','Attributes grow when you complete quests. Each point is tied to recorded effort.',btn('View Quests','quests','ghost','swords'))}<div class="grid attribute-grid">${Object.entries(ATTRS).map(([name,a])=>{const x=state.attributes[name];const gain=x.lifetime;return `<article class="panel attribute-card"><div class="attribute-title"><div class="attribute-symbol">${icon(a.icon)}</div><div><h3>${name}</h3><p>CHARACTER ATTRIBUTE</p></div></div><div class="attribute-score"><strong>${x.value}</strong><span>POINTS</span></div><div class="track"><div class="track-fill" style="width:${Math.min(100,x.value)}%"></div></div><p class="attribute-desc mt-15">${a.desc}</p><div class="attribute-foot"><span>LIFETIME GAIN</span><span>+${gain}</span></div><div class="separator"></div><div class="help-text">RELATED: ${a.categories.join(' · ')}</div></article>`}).join('')}</div><div class="notice-box mt-15">STAT RULE: Trivial/Easy quests grant +1 point, Normal/Hard +2, and Elite/Legendary +3 to the selected or category-mapped attributes. The same completion cannot grant points twice.</div>`}
function renderGoals(){const goals=state.goals.filter(g=>g.status!=='Archived');return `${heading('LONG-TERM OBJECTIVES','Main Quests','Turn your biggest ambitions into milestones. Link regular quests to a goal to add progress.',btn('New Main Quest','new-goal','primary','plus'))}${goals.length?`<div class="goal-cards">${goals.map(g=>`<article class="panel goal-card"><div class="panel-head"><span class="tag violet">${escapeHTML(g.category)}</span><button class="icon-action" data-edit-goal="${g.id}" aria-label="Edit goal">${icon('edit')}</button></div><h3>${escapeHTML(g.title)}</h3><p>${escapeHTML(g.description||'No description provided.')}</p><div class="goal-line"><strong>OBJECTIVE PROGRESS</strong><span>${g.progress}%</span></div><div class="track"><div class="track-fill" style="width:${g.progress}%"></div></div><div class="goal-meta"><span>${g.targetDate?'TARGET '+niceDate(g.targetDate):'NO DEADLINE'}</span><span>${g.status.toUpperCase()}</span></div><div class="separator"></div><div class="panel-head"><h3>Milestones</h3><span class="tag">${g.milestones.filter(m=>m.done).length}/${g.milestones.length}</span></div><div class="milestone-list">${g.milestones.length?g.milestones.map(m=>`<label class="milestone ${m.done?'done':''}"><input type="checkbox" data-milestone="${g.id}:${m.id}" ${m.done?'checked':''}><span>${escapeHTML(m.title)}</span></label>`).join(''):'<span class="help-text">No milestones yet. Edit this goal to add some.</span>'}</div><div class="goal-card-foot"><button class="btn small ghost" data-goal-progress="${g.id}">${icon('activity')} Update progress</button><button class="btn small ${g.status==='Completed'?'ghost':'primary'}" data-goal-complete="${g.id}">${icon('check')} ${g.status==='Completed'?'Mark active':'Complete'}</button></div></article>`).join('')}</div>`:empty('Your main quest awaits','Choose a meaningful long-term goal and break it into milestones.','new-goal','Create main quest','target')}<div class="notice-box mt-15">Linked quest completions only contribute to a main quest when a contribution percentage is explicitly configured.</div>`}
function renderAchievements(){return `${heading('MILESTONES OF HONOR','Achievements','Badges are unlocked automatically from your recorded activity. No achievement is granted by sample data.',`<span class="tag green">${Object.keys(state.achievements).length} / ${ACHIEVEMENTS.length} UNLOCKED</span>`)}<div class="grid achievement-grid">${ACHIEVEMENTS.map(a=>{const u=state.achievements[a.id];return `<article class="panel achievement-card ${u?'':'locked'}"><div class="achievement-icon">${icon(a.icon)}</div><h3>${a.name}</h3><p>${a.desc}</p><div class="${u?'unlocked-label':'locked-label'}">${u?`✓ UNLOCKED · ${niceDate(dateKey(new Date(u.unlockedAt)))}`:'◈ LOCKED ACHIEVEMENT'}</div></article>`}).join('')}</div>`}
function renderAnalytics(){const range=window.analyticsRange||'30';const cutoff=range==='all'?'0000-00-00':shiftDate(dateKey(),-Number(range)+1);const cs=state.completions.filter(c=>c.date>=cutoff).sort((a,b)=>a.date.localeCompare(b.date));const tx=state.transactions.filter(t=>t.date>=cutoff);const xp=tx.reduce((n,t)=>n+t.amount,0);const days=new Map();cs.forEach(c=>days.set(c.date,(days.get(c.date)||0)+c.xp));const slots=Array.from({length:7},(_,i)=>{const d=shiftDate(dateKey(),i-6);return {d,label:new Date(d+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'}),value:days.get(d)||0}});const max=Math.max(1,...slots.map(x=>x.value));const cats={};cs.forEach(c=>cats[c.category]=(cats[c.category]||0)+1);const palette=['#4ca7ff','#9a8cff','#6ee7b7','#ffc875','#ff7e92','#6ce8ff','#d9a4ff','#93a9c5'];const catItems=Object.entries(cats).sort((a,b)=>b[1]-a[1]);const totalCat=catItems.reduce((n,x)=>n+x[1],0);let cursor=0;const stops=catItems.map(([k,v],i)=>{const start=cursor;cursor+=totalCat?v/totalCat*100:0;return `${palette[i%palette.length]} ${start}% ${cursor}%`}).join(', ');const streak=state.streak||computeStreak();const heat=Array.from({length:84},(_,i)=>{const d=shiftDate(dateKey(),i-83),n=state.completions.filter(c=>c.date===d).length;return `<div class="heat-cell ${n>=4?'l4':n===3?'l3':n===2?'l2':n===1?'l1':''}" title="${d}: ${n} quests"></div>`}).join('');return `${heading('YOUR DATA, YOUR GROWTH','History & Analytics','A transparent view of real recorded completions. Weeks begin on Monday.',`<select class="select" id="analytics-range"><option value="7" ${range==='7'?'selected':''}>Last 7 days</option><option value="30" ${range==='30'?'selected':''}>Last 30 days</option><option value="90" ${range==='90'?'selected':''}>Last 90 days</option><option value="all" ${range==='all'?'selected':''}>All time</option></select>`)}<div class="grid analytics-grid">${metric('LIFETIME XP',state.profile.lifetimeXP.toLocaleString(),`${xp>=0?'+':''}${xp} XP in selected range`,'zap')}${metric('QUESTS COMPLETED',cs.length,'In selected range','check')}${metric('CURRENT STREAK',streak.current,`Longest: ${streak.longest} days`,'flame')}${metric('AVG. DAILY QUESTS',range==='all'?(state.streak.activeDays?(state.completions.length/state.streak.activeDays).toFixed(1):'0.0'):(cs.length/Math.max(1,Math.min(Number(range)||state.streak.activeDays,Number(range)||state.streak.activeDays))).toFixed(1),'Selected range average','activity')}</div><div class="grid chart-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2>✧ XP Earned</h2><p class="subhead" style="margin-top:5px">Daily XP over the last seven calendar days.</p></div><span class="tag blue">REAL DATA</span></div><div class="bar-chart">${slots.map(s=>`<div class="bar-column"><span class="bar-value">${s.value||''}</span><div class="bar" style="height:${s.value?Math.max(4,s.value/max*100):1}%"></div><span class="bar-label">${s.label}</span></div>`).join('')}</div></section><section class="panel chart-panel"><div class="panel-head"><div><h2>◈ Quest Categories</h2><p class="subhead" style="margin-top:5px">Completion mix for selected range.</p></div></div>${totalCat?`<div class="donut-layout"><div class="donut" style="background:conic-gradient(${stops})"><div class="donut-center"><strong>${totalCat}</strong><span>QUESTS</span></div></div><div class="legend">${catItems.map(([k,v],i)=>`<div class="legend-item"><i class="legend-dot" style="background:${palette[i%palette.length]}"></i><span>${escapeHTML(k)}</span><strong>${v}</strong></div>`).join('')}</div></div>`:empty('No category data','Complete quests to see your category distribution.')}</section></div><section class="panel panel-pad mt-15"><div class="panel-head"><div><h2>▦ Activity Heatmap</h2><p class="subhead" style="margin-top:5px">Last 12 weeks · each square is one calendar day.</p></div><span class="tag">84 DAYS</span></div><div class="heatmap">${heat}</div><div class="heat-legend">LESS <i class="heat-cell"></i><i class="heat-cell l1"></i><i class="heat-cell l2"></i><i class="heat-cell l3"></i><i class="heat-cell l4"></i> MORE</div></section><section class="panel panel-pad mt-15"><div class="panel-head"><div><h2>◷ Recent History</h2><p class="subhead" style="margin-top:5px">The latest records in your activity ledger.</p></div><span class="tag">${cs.length} EVENTS</span></div>${cs.length?`<div class="history-list">${cs.slice().reverse().slice(0,15).map(c=>`<div class="history-row"><div class="history-date">${niceDate(c.date,{month:'short',day:'numeric',year:'numeric'})}</div><div><div class="history-title">${escapeHTML(c.title)}</div><div class="history-sub">${escapeHTML(c.category)} · ${escapeHTML(c.difficulty)}</div></div><div class="history-xp">+${c.xp} XP</div></div>`).join('')}</div>`:empty('No records in this range','Your analytics will fill with actual progress as you complete quests.')}</section>`}
let focusInterval=null;
function renderFocus(){const f=state.focus;if(f.running&&f.endsAt){f.remaining=Math.max(0,Math.ceil((f.endsAt-Date.now())/1000));if(f.remaining===0){finishFocus()}}const total=(f.mode==='focus'?f.duration:(f.mode==='short'?state.settings.shortBreak:state.settings.longBreak))*60;const mins=String(Math.floor(f.remaining/60)).padStart(2,'0'),secs=String(f.remaining%60).padStart(2,'0'),pct=clamp((1-f.remaining/Math.max(1,total))*100,0,100);return `${heading('DEEP WORK PROTOCOL','Focus Mode','A quiet space for deliberate work. Time passing alone never grants XP.',`<span class="tag blue">POMODORO</span>`)}<div class="focus-screen"><section class="panel focus-card"><div class="eyebrow" style="justify-content:center">SYSTEM FOCUS / ${f.mode.toUpperCase()}</div><h2 style="margin-top:12px;font-size:22px">${f.mode==='focus'?'Enter the zone.':'Recover with intention.'}</h2><p class="subhead">${f.mode==='focus'?'One task. One session. Protect your attention.':'A short reset helps you return stronger.'}</p><div class="timer-ring" style="--timer-progress:${pct}%"><div class="timer-text"><strong id="timer-display">${mins}:${secs}</strong><span>${f.running?'SESSION IN PROGRESS':f.remaining===0?'SESSION COMPLETE':'READY WHEN YOU ARE'}</span></div></div><div class="form-group" style="max-width:330px;margin:0 auto 20px;text-align:left"><label for="focus-quest">ASSOCIATE WITH QUEST (OPTIONAL)</label><select class="select" id="focus-quest"><option value="">No quest selected</option>${state.quests.filter(q=>!q.archived).map(q=>`<option value="${q.id}" ${f.associatedQuest===q.id?'selected':''}>${escapeHTML(q.title)}</option>`).join('')}</select></div><div class="timer-controls">${f.running?`<button class="btn primary" data-focus="pause">${icon('clock')} Pause</button>`:`<button class="btn primary" data-focus="start">${icon('zap')} ${f.remaining===total?'Start focus':'Resume session'}</button>`}<button class="btn ghost" data-focus="reset">${icon('refresh')} Reset</button></div><div class="focus-meta"><span>◷ ${f.duration} MIN FOCUS</span><span>☕ ${state.settings.shortBreak} MIN SHORT BREAK</span><span>⏳ ${state.settings.longBreak} MIN LONG BREAK</span></div><div class="separator"></div><div class="pill-row" style="justify-content:center"><button class="btn small ${f.mode==='focus'?'primary':'ghost'}" data-focus-mode="focus">Focus</button><button class="btn small ${f.mode==='short'?'primary':'ghost'}" data-focus-mode="short">Short break</button><button class="btn small ${f.mode==='long'?'primary':'ghost'}" data-focus-mode="long">Long break</button></div></section><section class="panel panel-pad mt-15"><div class="panel-head"><div><h2>◷ Session History</h2><p class="subhead" style="margin-top:5px">Completed focus sessions are tracked here.</p></div><span class="tag">${state.focusSessions.length} SESSIONS</span></div>${state.focusSessions.length?`<div class="history-list">${state.focusSessions.slice().reverse().slice(0,8).map(s=>`<div class="history-row"><div class="history-date">${niceDate(s.date,{month:'short',day:'numeric'})}</div><div><div class="history-title">${escapeHTML(s.questTitle||'Independent focus session')}</div><div class="history-sub">${s.minutes} minute ${s.mode} session</div></div><div class="history-xp">COMPLETE</div></div>`).join('')}</div>`:empty('No focus sessions yet','Start a session and complete the timer to record it.')}</section></div>`}
function finishFocus(){const f=state.focus;if(!f.running)return;f.running=false;f.remaining=0;f.endsAt=null;if(f.mode==='focus'){const q=state.quests.find(q=>q.id===f.associatedQuest);state.focusSessions.push({id:uid(),date:dateKey(),at:stamp(),minutes:f.duration,mode:f.mode,questId:q?.id||'',questTitle:q?.title||''});toast('FOCUS SESSION COMPLETE',`${f.duration} minutes of focused effort recorded.`,'success')}saveState();if(window.currentPage==='focus')render()}
function renderSettings(){return `${heading('CONFIGURE YOUR SYSTEM','System Settings','Personalize the rules, appearance, focus timer, and data portability.',`<span class="tag blue">LOCAL PROFILE</span>`)}<div class="settings-grid"><section class="panel settings-card"><div class="panel-head"><div><h2>◈ Hunter Profile</h2><p class="subhead" style="margin-top:5px">Your identity and long-term purpose.</p></div></div><form id="settings-profile" class="form-grid"><div class="form-group"><label>Player name</label><input class="field" name="name" maxlength="32" required value="${escapeHTML(state.profile.name)}"></div><div class="form-group"><label>Avatar / emblem</label><select class="select" name="avatar">${['⚔️','🛡️','🦅','🐺','🔥','🌌','🧠','⚡','🦊','🐉'].map(a=>`<option ${state.profile.avatar===a?'selected':''}>${a}</option>`).join('')}</select></div><div class="form-group full"><label>Primary life goal</label><textarea class="textarea" name="goal" maxlength="140">${escapeHTML(state.profile.goal)}</textarea></div><div class="form-group full"><button class="btn primary">Save profile</button></div></form></section><section class="panel settings-card"><div class="panel-head"><div><h2>✧ Difficulty &amp; Rewards</h2><p class="subhead" style="margin-top:5px">Default XP values for new quests.</p></div></div><form id="settings-rewards"><div class="reward-grid">${Object.keys(DIFFICULTIES).map(d=>`<div class="reward-input"><label>${d.toUpperCase()}</label><input class="field" name="${d}" type="number" min="1" max="500" value="${state.settings.rewards[d]}"></div>`).join('')}</div><div class="settings-actions"><button class="btn primary">Save XP values</button></div></form><p class="help-text mt-15">Changing rewards affects future quest defaults. Existing quests keep their assigned XP.</p></section><section class="panel settings-card"><div class="panel-head"><div><h2>⚙️ Preferences</h2><p class="subhead" style="margin-top:5px">Tune how the system behaves.</p></div></div><div class="form-grid"><div class="form-group"><label>Week begins on</label><select class="select" id="setting-week"><option value="1" ${state.settings.weekStart===1?'selected':''}>Monday</option><option value="0" ${state.settings.weekStart===0?'selected':''}>Sunday</option></select></div><div class="form-group"><label>Morning cutoff hour</label><select class="select" id="setting-morning">${Array.from({length:12},(_,i)=>i+4).map(h=>`<option value="${h}" ${state.settings.morningCutoff===h?'selected':''}>${h}:00</option>`).join('')}</select></div><div class="form-group"><label>Focus duration (minutes)</label><input class="field" id="setting-focus" type="number" min="5" max="180" value="${state.settings.focusMinutes}"></div><div class="form-group"><label>Short break (minutes)</label><input class="field" id="setting-short" type="number" min="1" max="30" value="${state.settings.shortBreak}"></div><div class="form-group"><label>Long break (minutes)</label><input class="field" id="setting-long" type="number" min="5" max="60" value="${state.settings.longBreak}"></div></div><div class="separator"></div><label class="toggle-row">Reduced motion <input class="toggle" id="setting-motion" type="checkbox" ${state.settings.reducedMotion?'checked':''}></label><label class="toggle-row">Sound effects (reserved; no sound plays by default) <input class="toggle" id="setting-sound" type="checkbox" ${state.settings.sound?'checked':''}></label><label class="toggle-row">Confirm before deleting quests <input class="toggle" id="setting-delete" type="checkbox" ${state.settings.confirmDelete?'checked':''}></label><div class="settings-actions"><button class="btn primary" id="save-preferences">${icon('check')} Save preferences</button></div></section><section class="panel settings-card"><div class="panel-head"><div><h2>⇅ Data Management</h2><p class="subhead" style="margin-top:5px">Export a backup or restore your saved data.</p></div></div><div class="notice-box">Your progress is stored in LocalStorage for this browser and website origin. It does not sync between devices and may be lost if browser data is cleared. Export backups regularly.</div><div class="settings-actions"><button class="btn primary" data-action="export">${icon('download')} Export JSON</button><label class="btn ghost" for="import-file">${icon('upload')} Import JSON</label><input class="sr-only" id="import-file" type="file" accept=".json,application/json"><button class="btn ghost" data-action="defaults">${icon('refresh')} Restore defaults</button><button class="btn danger" data-action="reset">${icon('trash')} Reset all data</button></div><p class="help-text mt-15">Import validates the file before replacing current progress. Reset requires confirmation.</p></section></div>`}
function wireCommon(){ $$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('#quick-add').onclick=()=>questForm();$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#avatar-mini').onclick=()=>navigate('character');$('#sidebar').querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>$('#sidebar').classList.remove('open')))}
function navigate(page){window.currentPage=page;$('#sidebar').classList.remove('open');render();$('#view').focus({preventScroll:true});window.scrollTo({top:0,behavior:state.settings.reducedMotion?'auto':'smooth'})}
function wirePage(page){const view=$('#view');view.querySelectorAll('[data-action="new-quest"]').forEach(b=>b.onclick=()=>questForm());view.querySelectorAll('[data-action="new-goal"]').forEach(b=>b.onclick=()=>goalForm());view.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>completeQuest(b.dataset.complete));view.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>questForm(b.dataset.edit));view.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteQuest(b.dataset.delete));view.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>undoCompletion(b.dataset.undo));view.querySelectorAll('[data-edit-goal]').forEach(b=>b.onclick=()=>goalForm(b.dataset.editGoal));view.querySelectorAll('[data-milestone]').forEach(b=>b.onchange=()=>{const [gid,mid]=b.dataset.milestone.split(':');const g=state.goals.find(x=>x.id===gid),m=g?.milestones.find(x=>x.id===mid);if(m){m.done=b.checked;const pct=g.milestones.length?Math.round(g.milestones.filter(x=>x.done).length/g.milestones.length*100):g.progress;g.progress=Math.max(g.progress,pct);if(g.progress===100)g.status='Completed';saveState();render()}});view.querySelectorAll('[data-goal-progress]').forEach(b=>b.onclick=()=>{const g=state.goals.find(x=>x.id===b.dataset.goalProgress);if(!g)return;const v=prompt('Set main quest progress from 0 to 100:',String(g.progress));if(v===null)return;if(!/^\d+$/.test(v)||Number(v)>100){toast('INVALID PROGRESS','Enter a whole number from 0 to 100.','warning');return}g.progress=Number(v);if(g.progress<100&&g.status==='Completed')g.status='Active';if(g.progress===100)g.status='Completed';saveState();render()});view.querySelectorAll('[data-goal-complete]').forEach(b=>b.onclick=()=>{const g=state.goals.find(x=>x.id===b.dataset.goalComplete);if(!g)return;if(g.status==='Completed'){g.status='Active';g.progress=Math.min(g.progress,99)}else{g.status='Completed';g.progress=100}saveState();render();toast('MAIN QUEST UPDATED',g.title,'success')});
if(page==='quests'){const search=$('#quest-search'),cat=$('#filter-category'),diff=$('#filter-difficulty'),status=$('#filter-status'),sort=$('#sort-quests');const filter=()=>{let qs=state.quests.filter(q=>!q.archived);const s=search.value.toLowerCase();qs=qs.filter(q=>(q.title+' '+q.description).toLowerCase().includes(s)&&(!cat.value||q.category===cat.value)&&(!diff.value||q.difficulty===diff.value));if(status.value==='active')qs=qs.filter(q=>!q.completed||q.repeat!=='Never');if(status.value==='completed')qs=qs.filter(q=>q.completed);qs.sort((a,b)=>sort.value==='xp'?b.xp-a.xp:sort.value==='difficulty'?Object.keys(DIFFICULTIES).indexOf(b.difficulty)-Object.keys(DIFFICULTIES).indexOf(a.difficulty):sort.value==='due'?(a.dueDate||'9999').localeCompare(b.dueDate||'9999'):b.createdAt.localeCompare(a.createdAt));$('#quest-card-list').innerHTML=qs.length?qs.map(questCard).join(''):empty('No matching quests','Adjust your filters or create a new quest.','new-quest','Create quest','swords');$('#quest-count').textContent=qs.length;wirePage('quests')};[search,cat,diff,status,sort].forEach(el=>el.addEventListener('input',filter))}
if(page==='character'){view.querySelector('[data-action="edit-profile"]')?.addEventListener('click',()=>navigate('settings'))}
if(page==='analytics'){$('#analytics-range').onchange=e=>{window.analyticsRange=e.target.value;render()}}
if(page==='focus'){const sel=$('#focus-quest');sel.onchange=()=>{state.focus.associatedQuest=sel.value;saveState()};view.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{const f=state.focus;if(b.dataset.focus==='start'){if(!f.running){if(f.remaining<=0)f.remaining=(f.mode==='focus'?f.duration:f.mode==='short'?state.settings.shortBreak:state.settings.longBreak)*60;f.running=true;f.endsAt=Date.now()+f.remaining*1000;saveState();render();startFocusTick()}}else if(b.dataset.focus==='pause'){f.remaining=Math.max(0,Math.ceil((f.endsAt-Date.now())/1000));f.running=false;f.endsAt=null;saveState();render();clearInterval(focusInterval)}else{f.running=false;f.endsAt=null;f.remaining=(f.mode==='focus'?f.duration:f.mode==='short'?state.settings.shortBreak:state.settings.longBreak)*60;saveState();render();clearInterval(focusInterval)}});view.querySelectorAll('[data-focus-mode]').forEach(b=>b.onclick=()=>{state.focus.running=false;state.focus.endsAt=null;state.focus.mode=b.dataset.focusMode;state.focus.duration=state.settings.focusMinutes;state.focus.remaining=(state.focus.mode==='focus'?state.settings.focusMinutes:state.focus.mode==='short'?state.settings.shortBreak:state.settings.longBreak)*60;saveState();render();clearInterval(focusInterval)})}
if(page==='settings'){const profile=$('#settings-profile');profile.onsubmit=e=>{e.preventDefault();const fd=new FormData(profile);state.profile.name=fd.get('name').trim();state.profile.goal=fd.get('goal').trim();state.profile.avatar=fd.get('avatar');saveState();render();toast('PROFILE SAVED','Your hunter profile has been updated.','success')};$('#settings-rewards').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);Object.keys(DIFFICULTIES).forEach(k=>state.settings.rewards[k]=clamp(Number(fd.get(k))||DIFFICULTIES[k],1,500));saveState();render();toast('REWARDS UPDATED','Difficulty XP defaults saved.','success')};$('#save-preferences').onclick=e=>{e.preventDefault();state.settings.weekStart=Number($('#setting-week').value);state.settings.morningCutoff=Number($('#setting-morning').value);state.settings.focusMinutes=clamp(Number($('#setting-focus').value)||25,5,180);state.settings.shortBreak=clamp(Number($('#setting-short').value)||5,1,30);state.settings.longBreak=clamp(Number($('#setting-long').value)||15,5,60);state.settings.reducedMotion=$('#setting-motion').checked;state.settings.sound=$('#setting-sound').checked;state.settings.confirmDelete=$('#setting-delete').checked;if(!state.focus.running){state.focus.duration=state.settings.focusMinutes;if(state.focus.mode==='focus')state.focus.remaining=state.settings.focusMinutes*60}saveState();render();toast('PREFERENCES SAVED','System configuration updated.','success')};$('#import-file').onchange=importData}
}
function startFocusTick(){clearInterval(focusInterval);focusInterval=setInterval(()=>{if(!state.focus.running){clearInterval(focusInterval);return}state.focus.remaining=Math.max(0,Math.ceil((state.focus.endsAt-Date.now())/1000));const display=$('#timer-display');if(display)display.textContent=`${String(Math.floor(state.focus.remaining/60)).padStart(2,'0')}:${String(state.focus.remaining%60).padStart(2,'0')}`;const ring=$('.timer-ring');if(ring){const total=(state.focus.mode==='focus'?state.focus.duration:state.focus.mode==='short'?state.settings.shortBreak:state.settings.longBreak)*60;ring.style.setProperty('--timer-progress',`${clamp((1-state.focus.remaining/total)*100,0,100)}%`)}if(state.focus.remaining<=0){finishFocus();clearInterval(focusInterval)}},250)}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`arise-backup-${dateKey()}.json`;a.click();URL.revokeObjectURL(url);toast('BACKUP EXPORTED','Your ARISE data has been downloaded.','success')}
function importData(e){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const incoming=safeParse(reader.result);if(!validateState(incoming)||!Array.isArray(incoming.goals)||!Array.isArray(incoming.activityDays||[])){toast('IMPORT REJECTED','This file is invalid or is not an ARISE v1 backup. Current data was not changed.','warning');e.target.value='';return}if(!confirm('Import this backup and replace the current ARISE data? Export your current data first if needed.')){e.target.value='';return}try{const check=JSON.parse(JSON.stringify(incoming));if(!check.profile||!Number.isFinite(check.profile.lifetimeXP)||check.profile.lifetimeXP<0||check.quests.some(q=>!q.id||!q.title)||check.completions.some(c=>!c.id||!c.questId||!Number.isFinite(c.xp))){throw new Error('invalid fields')}state=Object.assign(defaultState(),check);saveState();render();toast('BACKUP RESTORED','Imported data passed validation.','success')}catch(err){toast('IMPORT REJECTED','The file contains invalid data. Existing progress remains unchanged.','warning')}e.target.value=''};reader.readAsText(file)}
function resetData(){if(!confirm('Reset ALL ARISE progress, quests, achievements, and history? This cannot be undone. Export a backup first if needed.'))return;try{localStorage.removeItem(STORE)}catch{}state=defaultState();saveState();$('#modal-root').innerHTML='';render();onboarding()}
function wireGlobal(){document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='export')exportData();if(action==='reset')resetData();if(action==='defaults'){if(confirm('Restore default settings without deleting progress?')){state.settings=defaultState().settings;saveState();render();toast('DEFAULTS RESTORED','Settings reset. Progress was preserved.','success')}}});window.addEventListener('storage',e=>{if(e.key===STORE){state=loadState();render();toast('SYSTEM SYNC','Another tab updated your local progress.')}});window.addEventListener('beforeunload',()=>{if(state.focus.running&&state.focus.endsAt)state.focus.remaining=Math.max(0,Math.ceil((state.focus.endsAt-Date.now())/1000));saveState()})}
function init(){refreshDerived();if(!state.setupComplete){onboarding()}else{render();toast('SYSTEM INITIALIZED','Your progression data is ready.','success')}wireGlobal();if(state.focus.running&&state.focus.endsAt){if(state.focus.endsAt<=Date.now()){finishFocus()}else startFocusTick()}}
init();
})();